script:
export const meta = {
  name: 'review_loop',
  description: 'Actor-Critic review→fix→re-review loop: adversarial verification, severity gating, scope-locking, per-round diff refresh, bounded convergence',
  phases: [{ title: 'Scope' }, { title: 'Converge' }, { title: 'Report' }],
}

// ---- Config (overridable via args; CLI key=value arrive as strings) ----
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d }
const scope         = (args && args.scope) || (args && args._) || 'the current branch vs its merge-base with main, else staged, else HEAD'
const maxRounds     = num(args && args.maxRounds, 5)
const reviewers     = num(args && args.reviewers, 2)
const threshold     = num(args && args.threshold, 0.5)
const maxChunkLines = num(args && args.maxChunkLines, 500)
let gate = (args && args.severityGate) || ['blocker', 'high']
if (typeof gate === 'string') gate = gate.split(',').map((s) => s.trim()).filter(Boolean)

const findingSchema = {
  type: 'object',
  properties: { findings: { type: 'array', items: { type: 'object', properties: {
    id: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'high', 'medium', 'suggestion'] },
    category: { type: 'string', enum: ['security', 'correctness', 'performance', 'maintainability'] },
    location: { type: 'string' }, description: { type: 'string' }, evidence: { type: 'string' },
    repro_test: { type: 'string' }, boundary_owner: { type: 'string', enum: ['current', 'server', 'external'] },
    confidence: { type: 'string', enum: ['low', 'medium', 'high'] },
  }, required: ['id', 'severity', 'category', 'location', 'description', 'boundary_owner'] } } },
  required: ['findings'],
}

// Stable identity + de-duplication (critic ids are non-deterministic across
// rounds, so key on category+location to detect no-progress / oscillation).
const keyOf = (f) => (f.category || '?') + '|' + (f.location || '?')
const dedup = (arr) => {
  const seen = {}
  const out = []
  for (const f of arr) { const k = keyOf(f); if (!seen[k]) { seen[k] = true; out.push(f) } }
  return out
}

const RULES_HEAD =
  '\n\nRULES: Comment ONLY on the diff below plus at most one hop of direct dependencies. Flag issues; do NOT rewrite code. ' +
  'Severity blocker/high = crashes, security, logic bugs, measurable perf/arch regressions; medium/suggestion = style, micro-opts, speculative edge cases. ' +
  'Set boundary_owner=current only if the fix belongs in THIS diff. For every blocker/high include a concrete repro_test that fails on current behavior. Quote evidence.\n\nDIFF:\n'
const buildRules = (d) => RULES_HEAD + d

// ---- Phase 1: resolve scope, capture diff, size-gate ----
phase('Scope')
const scan = await agent(
  'Resolve review scope: ' + scope + '. Run git to capture the unified diff and changed files. ' +
  'Return the diff, the changed-file list, and total added+removed line count.',
  { tier: 'small', label: 'scope + diff', schema: { type: 'object', properties: {
      diff: { type: 'string' }, files: { type: 'array', items: { type: 'string' } }, lineCount: { type: 'number' }
    }, required: ['diff', 'files', 'lineCount'] } })
if (!scan || typeof scan.diff !== 'string') {
  return { verdict: 'ABORTED — could not resolve scope/diff', roundsRun: 0, totalFixed: 0,
           unresolved: [], unverified: [], tracked: [], trajectory: [], report: 'Scope agent returned no usable diff.' }
}
let currentDiff = scan.diff
const oversized = scan.lineCount > maxChunkLines
if (oversized) log('PR is ' + scan.lineCount + ' lines (> ' + maxChunkLines + '); large diffs converge poorly — skipping the loop and flagging NEEDS SPLIT.')

// ---- Phase 2: bounded Actor-Critic convergence loop ----
phase('Converge')
let lastSurvivors = []
let roundsRun = 0
const tracked = []
const unverified = []
const fixLog = []
const trajectory = []
let found = []

if (!oversized) {
  found = await loopUntilDry({
    maxRounds, consecutiveEmpty: 2, key: keyOf,
    round: async (r) => {
      roundsRun = r + 1

      // P0: refresh the diff each round so critics review the CURRENT (post-fix)
      // state instead of a frozen round-0 snapshot. Without this the loop keeps
      // re-flagging already-fixed issues and can never observe convergence.
      if (r > 0) {
        const rescan = await agent(
          'Re-capture the CURRENT unified diff for review scope: ' + scope +
          ' (it now reflects fixes applied in prior rounds). Return the diff and total added+removed line count.',
          { tier: 'small', label: 'rescan r' + roundsRun, schema: { type: 'object', properties: {
              diff: { type: 'string' }, lineCount: { type: 'number' } }, required: ['diff'] } })
        if (rescan && typeof rescan.diff === 'string') currentDiff = rescan.diff
        else log('Rescan in round ' + roundsRun + ' returned null; reusing prior diff snapshot (may be stale).')
      }
      const rules = buildRules(currentDiff)

      // CRITIC: independent isolated lanes (separate sessions => no self-agreeableness).
      // All three critics run on criticBig (a DIFFERENT model family than the fixerBig
      // fixer) to decorrelate blind spots on the re-review of each fix.
      const laneNames = ['maintainability', 'correctness', 'security']
      const lanes = await parallel([
        () => agent('Read the skill file at ~/.agents/skills/thermo-nuclear-code-quality-review/SKILL.md (expand ~ to your home dir) and apply it as a maintainability critic.' + rules,
                    { tier: 'criticBig', label: 'maintainability r' + roundsRun, schema: findingSchema }),
        () => agent('Correctness critic: trace the most critical path end-to-end; logic bugs, missing authz, boundary/edge errors.' + rules,
                    { tier: 'criticBig', label: 'correctness r' + roundsRun, schema: findingSchema }),
        () => agent('Security critic: injection, secrets, authz, unsafe handling of untrusted input.' + rules,
                    { tier: 'criticBig', label: 'security r' + roundsRun, schema: findingSchema }),
      ])
      // Record missing coverage (a failed lens is not "clean").
      lanes.forEach((l, i) => { if (!l) log('Critic lane "' + laneNames[i] + '" returned null (missing coverage) in round ' + roundsRun + '.') })
      const all = lanes.filter(Boolean).flatMap((l) => (l && l.findings) || [])

      // CLASSIFY: loop-drivers vs tracked-for-later
      const gated = []
      for (const f of all) {
        if (gate.indexOf(f.severity) >= 0 && f.boundary_owner === 'current') gated.push(f)
        else tracked.push(f)
      }
      if (!gated.length) {
        trajectory.push({ round: roundsRun, lanesOk: lanes.filter(Boolean).length, findings: all.length, gated: 0, survivors: 0, unverified: 0, fixed: 0 })
        lastSurvivors = []
        return []
      }

      // VERIFY: adversarial skeptics must REFUTE; only survivors proceed.
      const checks = await parallel(gated.map((f) => () =>
        verify('Category ' + f.category + ' at ' + f.location + ': ' + f.description +
               '\nClaimed repro: ' + (f.repro_test || '(none)') +
               '\nREAL only if the repro would truly fail on current behavior and the fix belongs in this diff.',
               { reviewers, threshold, lens: [f.category, 'is this edge case already implicitly handled?'] })))
      // A NULL verify is missing coverage, NOT a refutation — escalate rather than
      // silently drop a potentially-real blocker.
      const survivors = []
      let unverifiedThisRound = 0
      gated.forEach((f, i) => {
        const c = checks[i]
        if (!c) { unverified.push(f); unverifiedThisRound++; log('Verification failed for ' + keyOf(f) + ' in round ' + roundsRun + '; routing to human escalation (not silently dropped).') }
        else if (c.real) survivors.push(f)
      })
      lastSurvivors = survivors
      trajectory.push({ round: roundsRun, lanesOk: lanes.filter(Boolean).length, findings: all.length, gated: gated.length, survivors: survivors.length, unverified: unverifiedThisRound, fixed: survivors.length })
      if (!survivors.length) return []

      // ACTOR: single fixer holds fix authority; fixes survivors ONLY, adds
      // failing->passing tests, stays in scope. Runs on fixerBig (distinct family).
      const fix = await agent(
        'You are the fixer. Apply MINIMAL fixes for ONLY these verified blockers, add a test that fails before / passes after each, ' +
        'stay within the diff scope, then report what changed.\n\n' + JSON.stringify(survivors),
        { tier: 'fixerBig', label: 'fix r' + roundsRun })
      fixLog.push({ round: roundsRun, fixed: survivors.length, summary: fix })
      return survivors
    },
  })
}

// ---- Phase 3: report + verdict + escalation ----
phase('Report')
const trackedUnique = dedup(tracked)
const unverifiedUnique = dedup(unverified)
const verdict =
    oversized ? 'NEEDS SPLIT — too large to converge; split then re-run'
  : (lastSurvivors.length > 0 && roundsRun >= maxRounds) ? 'STOPPED AT CAP — escalate to human'
  : lastSurvivors.length === 0 ? 'CONVERGED CLEAN'
  : 'STOPPED — no new blockers (possible oscillation on remaining items)'

const report = await agent(
  'Write a concise final report: verdict, per-round trajectory, resolution rate (fixed/total gated), ' +
  'unresolved blockers to escalate, findings that could NOT be verified (escalate to human), and the tracked-for-later list. ' +
  'Do NOT re-litigate resolved items.\n\n' +
  'VERDICT: ' + verdict + '\nROUNDS: ' + roundsRun +
  '\nTRAJECTORY:\n' + JSON.stringify(trajectory) +
  '\nFIX LOG:\n' + JSON.stringify(fixLog) +
  '\nUNRESOLVED:\n' + JSON.stringify(lastSurvivors) +
  '\nUNVERIFIED (verification failed — escalate):\n' + JSON.stringify(unverifiedUnique) +
  '\nTRACKED:\n' + JSON.stringify(trackedUnique),
  { tier: 'medium', label: 'synthesis' })

return { verdict, roundsRun, totalFixed: found.length, unresolved: lastSurvivors, unverified: unverifiedUnique, tracked: trackedUnique, trajectory, report }
